package com.example.starter.media.domain;

/**
 * 授权模式：独占 / 非独占。
 */
public enum LicenseMode {
    EXCLUSIVE,
    NON_EXCLUSIVE
}

package com.example.starter.media.domain;

/**
 * 授权版本状态。
 * ACTIVE：当前有效；SUPERSEDED：已被更正后的新版本替代；REVOKED：已撤销。
 */
public enum GrantStatus {
    ACTIVE,
    SUPERSEDED,
    REVOKED
}

package com.example.starter.media.domain;

/**
 * 排期时段状态。
 * BOUND：已绑定当时有效的授权版本；BLOCKED：授权被撤销且该时段尚未开始；PLAYED：已完成播出，证据冻结。
 */
public enum ScheduleItemStatus {
    BOUND,
    BLOCKED,
    PLAYED
}

package com.example.starter.media.web;

import org.springframework.http.HttpStatus;

/**
 * 业务错误，携带 HTTP 状态码与错误码。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }
}

