package com.example.starter.media.service;

/**
 * 幂等回放信号：同 requestId 同参数请求命中首次结果时抛出，
 * 由 Web 层以首次的状态码与响应体原样返回，不执行任何新的业务写入。
 */
public class ReplayException extends RuntimeException {

    private final int statusCode;
    private final String jsonBody;

    public ReplayException(int statusCode, String jsonBody) {
        super("idempotent replay");
        this.statusCode = statusCode;
        this.jsonBody = jsonBody;
    }

    public int getStatusCode() {
        return statusCode;
    }

    public String getJsonBody() {
        return jsonBody;
    }
}

